#!/usr/bin/env bash
# unityHPC/train_job.sh (llms-agents) — generated by /unity-hpc:connect. Do not hand-edit.
# Coordinated train launch, then rank-0 consolidate into checkpoint-final.
# UNITY_SCAFFOLD_VERSION=@@UNITY_HPC_VERSION@@
set -euo pipefail

REMOTE_DIR="${REMOTE_DIR/#\~/$HOME}"
cd "$REMOTE_DIR"
APP="${REMOTE_DIR}/unityHPC"

# Where this job's artifacts belong. `run.sh fetch` prefers this same path when
# it exists on the cluster, so a job that writes here is pulled one campaign at
# a time. Exported but NOT created here: an empty directory would satisfy
# fetch's prefer-if-present probe for a job that writes elsewhere.
export RESULTS_DIR="${REMOTE_RESULTS_DIR:-${REMOTE_DIR}/_results}/${CAMPAIGN}"

export PYTHONUNBUFFERED=1
export OMP_NUM_THREADS="${SLURM_CPUS_PER_TASK:-1}"
export PYTORCH_CUDA_ALLOC_CONF=expandable_segments:True

# Shared Hugging Face cache on the project /work directory. Do not point this
# at a node-local disk, and do not copy unityHPC/.env into the cache.
if [ -n "${HF_HOME:-}" ]; then
    export HF_HOME
fi
export LLMS_CACHE_DIR="${LLMS_CACHE_DIR:-${REMOTE_DIR}/_cache/llms-agents}"
export LLMS_CHECKPOINT_DIR="${LLMS_CHECKPOINT_DIR:-${RESULTS_DIR}/checkpoint-final}"

set +u
[[ -f /usr/share/lmod/lmod/init/bash ]] && . /usr/share/lmod/lmod/init/bash
set -u
if [ -n "${MODULES:-}" ]; then
    module purge && module load ${MODULES}
fi

# An optional unityHPC/bootstrap.sh replaces the VENV_PATH activate below.
# Sourced (not run in a subshell) so a hook that activates a venv or exports
# HF_HOME etc. affects this job. Serialised with flock on REMOTE_DIR so N
# fan-out tasks starting together do not race a venv build on shared NFS.
# The re-check after acquiring the lock is `if/then`, never `[ ... ] &&`: under
# `set -e` a false `&&` guard is itself a failing command and aborts the very
# path meant to handle "the hook exists."
if [ -f "unityHPC/bootstrap.sh" ]; then
    exec 9>"${REMOTE_DIR}/.unity_bootstrap.lock"
    flock 9
    if [ -f "unityHPC/bootstrap.sh" ]; then
        . "unityHPC/bootstrap.sh"
    fi
    flock -u 9
    exec 9>&-
else
    if [ -n "${VENV_PATH:-}" ] && [ -f "${VENV_PATH}/bin/activate" ]; then
        . "${VENV_PATH}/bin/activate"
    fi
fi

# Not `... | head -1 || echo unknown`: on a CPU node nvidia-smi writes
# "No devices were found" to STDOUT and exits non-zero, so under `set -o
# pipefail` head emits that text AND the fallback fires, and the banner ends up
# split over two lines with the error in the middle of it. Ask separately, then
# default.
GPU_NAME=""
if command -v nvidia-smi >/dev/null 2>&1; then
    GPU_NAME=$(nvidia-smi --query-gpu=name --format=csv,noheader 2>/dev/null | head -1 || true)
fi
case "$GPU_NAME" in ""|*"No devices"*) GPU_NAME="unknown" ;; esac
NODES="${SLURM_NNODES:-1}"
GPUS_PER_NODE="${SLURM_GPUS_ON_NODE:-${SLURM_GPUS:-1}}"
echo "=== $(date -u +%Y-%m-%dT%H:%M:%SZ) | exp=${EXP} | nodes=${NODES} | gpu=${GPU_NAME} ==="

# NCCL is the process-group backend. Copy of the ml template's rendezvous
# block, plus WORLD_SIZE and RANK for launchers that are not torchrun.
# torchrun sets WORLD_SIZE and RANK in the child. Accelerate and DeepSpeed
# still need both names in the environment before they start.
export NCCL_DEBUG=INFO
export TORCH_DISTRIBUTED_BACKEND=nccl
MASTER_ADDR=$(scontrol show hostnames "$SLURM_JOB_NODELIST" | head -1)
export MASTER_ADDR
export MASTER_PORT="${MASTER_PORT:-${LLMS_MASTER_PORT:-29500}}"
if [ "${LLMS_DISTRIBUTED:-torchrun}" != "torchrun" ]; then
    export WORLD_SIZE="${WORLD_SIZE:-$(( NODES * GPUS_PER_NODE ))}"
    export RANK="${RANK:-${SLURM_PROCID:-${SLURM_NODEID:-0}}}"
fi

LLMS_APP_DIR="$APP"
case "${LLMS_PARALLEL:-fsdp}" in
    deepspeed)
        LLMS_PARALLEL_CONFIG="${LLMS_APP_DIR}/configs/deepspeed_zero3.json"
        ;;
    *)
        LLMS_PARALLEL_CONFIG="${LLMS_APP_DIR}/configs/fsdp.yaml"
        ;;
esac
export LLMS_PARALLEL="${LLMS_PARALLEL:-fsdp}"
export LLMS_PARALLEL_CONFIG
case "${LLMS_OBJECTIVE:-sft}" in
    dpo|preference) TASK_CONFIG="${LLMS_APP_DIR}/configs/dpo.yaml" ;;
    *) TASK_CONFIG="${LLMS_APP_DIR}/configs/sft.yaml" ;;
esac

# Do not copy unityHPC/.env into the cache or the checkpoint directory.
runtime_config="$(mktemp)"
sed \
    -e "s#__CACHE__#${LLMS_CACHE_DIR}#g" \
    -e "s#__CHECKPOINT__#${LLMS_CHECKPOINT_DIR}#g" \
    -e "s#__PARALLEL__#${LLMS_PARALLEL_CONFIG}#g" \
    "$TASK_CONFIG" >"$runtime_config"

launch_train() {
    local launcher="${LLMS_LAUNCHER:-axolotl}"
    local distributed="${LLMS_DISTRIBUTED:-torchrun}"
    local module="axolotl.cli.train"
    local -a module_args=("$runtime_config")
    if [ "$launcher" = "trl" ]; then
        module="trl"
        module_args=(sft --config "$runtime_config")
    fi
    if [ "$distributed" = "torchrun" ]; then
        torchrun \
            --nnodes="$NODES" \
            --nproc_per_node="$GPUS_PER_NODE" \
            --rdzv_backend=c10d \
            --rdzv_endpoint="${MASTER_ADDR}:${MASTER_PORT}" \
            --node_rank="${SLURM_NODEID:-0}" \
            -m "$module" "${module_args[@]}"
    else
        accelerate launch --config_file "$LLMS_PARALLEL_CONFIG" \
            -m "$module" "${module_args[@]}"
    fi
}

consolidate_ranks() {
    # Global rank 0 writes the Hugging Face directory. Other ranks wait for
    # that write, then exit. torchrun visits every rank when the allocation
    # has more than one process. A single process is rank 0.
    export LLMS_CHECKPOINT_DIR
    if [ "$NODES" -gt 1 ] || [ "$GPUS_PER_NODE" -gt 1 ]; then
        torchrun \
            --nnodes="$NODES" \
            --nproc_per_node="$GPUS_PER_NODE" \
            --rdzv_backend=c10d \
            --rdzv_endpoint="${MASTER_ADDR}:${MASTER_PORT}" \
            --node_rank="${SLURM_NODEID:-0}" \
            "$APP/prep.py" consolidate \
            --dest "$LLMS_CHECKPOINT_DIR" \
            --shards "${RESULTS_DIR}/checkpoint-shards"
    else
        RANK=0 python3 "$APP/prep.py" consolidate \
            --dest "$LLMS_CHECKPOINT_DIR" \
            --shards "${RESULTS_DIR}/checkpoint-shards"
    fi
}

set +e
if [ "${LLMS_STAGE:-train}" != "consolidate" ]; then
    launch_train &
    TRAIN_PID=$!
    SAMPLER_PID=""
    if [ "${GPU_SAMPLE_INTERVAL:-0}" -gt 0 ] && command -v nvidia-smi >/dev/null 2>&1; then
        SAMPLE_FILE="${GPU_SAMPLE_FILE:-${RESULTS_DIR}/${EXP}-${SLURM_JOB_ID}.gpu.csv}"
        mkdir -p "$(dirname "$SAMPLE_FILE")"
        printf 'timestamp_utc,gpu_index,utilization_gpu,memory_used,memory_total,power_draw,temperature_gpu\n' >"$SAMPLE_FILE"
        (
            while kill -0 "$TRAIN_PID" 2>/dev/null; do
                timestamp="$(date -u +%Y-%m-%dT%H:%M:%SZ)"
                nvidia-smi --query-gpu=index,utilization.gpu,memory.used,memory.total,power.draw,temperature.gpu \
                    --format=csv,noheader,nounits 2>/dev/null \
                    | sed "s/^/${timestamp},/" >>"$SAMPLE_FILE" || true
                sleep "$GPU_SAMPLE_INTERVAL"
            done
        ) &
        SAMPLER_PID=$!
    fi
    wait "$TRAIN_PID"
    RC=$?
    if [ -n "$SAMPLER_PID" ]; then
        kill "$SAMPLER_PID" 2>/dev/null || true
        wait "$SAMPLER_PID" 2>/dev/null || true
    fi
else
    RC=0
fi
set -e
rm -f "$runtime_config"
if [ "$RC" -ne 0 ]; then
    echo "=== done $(date -u +%Y-%m-%dT%H:%M:%SZ) rc=${RC} ==="
    exit "$RC"
fi

# Consolidate runs in this allocation when the stage is train-and-consolidate,
# and on its own when LLMS_STAGE=consolidate. The eval stage reads
# $LLMS_CHECKPOINT_DIR, not the shard directory.
if [ "${LLMS_STAGE:-train}" != "train-only" ]; then
    consolidate_ranks
fi
echo "=== done $(date -u +%Y-%m-%dT%H:%M:%SZ) rc=0 checkpoint=${LLMS_CHECKPOINT_DIR} ==="
